import { useState } from "react";
export default function Form11() {
  const [form, setform] = useState({
    name: "",
    email: "",
    age: "",
    genralinfo: "",
  });
  return (
    <>
      <form>
        <div className="div1">
          <div>
            <label> name</label>
            <input
              value={form.name}
              onChange={(event) => {
                setform({ ...form, name: event.target.value });
              }}
            />
          </div>
          <div>
            <label> email</label>
            <input
              value={form.email}
              onChange={(event) => {
                setform({ ...form, email: event.target.value });
              }}
            />
          </div>
          <div>
            <label> age</label>
            <input
              value={form.age}
              onChange={(event) => {
                setform({ ...form, age: event.target.value });
              }}
            />
          </div>
        </div>
        <label>text area</label>
        <textarea></textarea>
        <button className="btn">sumbet</button>
      </form>
    </>
  );
}
